// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.noteimport com.roshan.persona.productivity.alarm.EncryptedDataimport com.roshan.persona.productivity.alarm.Fts5Utilsimport kotlinx.coroutines.runBlockingimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Room-backed Note Store (Module 13 v2 — audit P0 fix). * * Production [NoteStore] implementation backed by [NoteDao] + SQLCipher- * encrypted Room database. * * ## Why this matters * * **Previously**: `NoteEngine` hardcoded `NoteStore()` (in-memory map) as the * default. Notes were lost on process death. The `EncryptedNoteDatabase` + * `NoteDao` existed but were never wired — dead code. * * Now: `RoomNoteStore` delegates all operations to `NoteDao` via `runBlocking` * (the NoteEngine API is non-suspend for backwards compat). Data persists * across process death + reboots, encrypted at the file level by SQLCipher. * * ## FTS5 Search * * `search()` + `searchPrefix()` delegate to `NoteDao.search()` which runs a * real FTS4 MATCH query on the `notes_fts` virtual table. Query sanitization * happens here via [Fts5Utils.escapeFts5Query] / [Fts5Utils.buildPrefixQuery]. * * ## Entity ↔ NoteInfo conversion * * [NoteEntity] is the Room row representation; [NoteInfo] is the domain model * used by NoteEngine. [toEntity] + [toInfo] handle the conversion, including * serializing `EncryptedData` to byte arrays for Room storage. * * @see NoteStore * @see NoteDao * @see EncryptedNoteDatabase */@Singletonclass RoomNoteStore @Inject constructor(    private val noteDao: NoteDao,) : NoteStore {    override fun put(note: NoteInfo) {        runBlocking {            try {                noteDao.upsert(note.toEntity())            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "put failed for note ${note.id}")            }        }    }    override fun getById(id: String): NoteInfo? {        return runBlocking {            try {                noteDao.getById(id)?.toInfo()            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "getById failed for note $id")                null            }        }    }    override fun getAll(): List<NoteInfo> {        return runBlocking {            try {                noteDao.getAll().map { it.toInfo() }            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "getAll failed")                emptyList()            }        }    }    override fun getByTag(tag: String): List<NoteInfo> {        return runBlocking {            try {                noteDao.getByTag(tag).map { it.toInfo() }            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "getByTag failed for tag $tag")                emptyList()            }        }    }    override fun deleteById(id: String): Boolean {        return runBlocking {            try {                noteDao.deleteById(id) > 0            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "deleteById failed for note $id")                false            }        }    }    override fun search(query: String): List<NoteInfo> {        if (query.isBlank()) return emptyList()        return runBlocking {            try {                val sanitized = Fts5Utils.escapeFts5Query(query)                noteDao.search(sanitized).map { it.toInfo() }            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "search failed for query: $query")                emptyList()            }        }    }    override fun searchPrefix(query: String): List<NoteInfo> {        if (query.isBlank()) return emptyList()        return runBlocking {            try {                val prefixQuery = Fts5Utils.buildPrefixQuery(query)                noteDao.searchPrefix(prefixQuery).map { it.toInfo() }            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "searchPrefix failed for query: $query")                emptyList()            }        }    }    override fun count(): Int {        return runBlocking {            try {                noteDao.count()            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "count failed")                0            }        }    }    override fun clear() {        runBlocking {            try {                noteDao.deleteAll()            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "clear failed")            }        }    }    private companion object {        private const val TAG = "RoomNoteStore"    }}// ─── Entity ↔ NoteInfo conversion ──────────────────────────────────────────/** * Convert [NoteInfo] to [NoteEntity] for Room storage. * * EncryptedData already stores IV + ciphertext as Base64 strings — we copy * them directly to the entity columns. */internal fun NoteInfo.toEntity(): NoteEntity {    return NoteEntity(        id = id,        title = title,        bodyIv = encryptedBody?.ivBase64,        bodyCiphertext = encryptedBody?.ciphertextBase64,        plainTextBody = plainTextBody,        contentType = contentType.name,        tags = tags.joinToString(","),        createdAtMs = createdAtMs,        updatedAtMs = updatedAtMs,    )}/** * Convert [NoteEntity] back to [NoteInfo]. */internal fun NoteEntity.toInfo(): NoteInfo {    val encData = if (!bodyIv.isNullOrBlank() && !bodyCiphertext.isNullOrBlank()) {        EncryptedData(            ivBase64 = bodyIv,            ciphertextBase64 = bodyCiphertext,        )    } else null    return NoteInfo(        id = id,        title = title,        encryptedBody = encData,        plainTextBody = plainTextBody,        contentType = try {            NoteContentType.valueOf(contentType)        } catch (e: IllegalArgumentException) {            NoteContentType.TEXT        },        tags = if (tags.isBlank()) emptyList() else tags.split(","),        createdAtMs = createdAtMs,        updatedAtMs = updatedAtMs,    )}